+  }
+
+  #sweep() {
+    if (this.#adapter.closed) return;
+    let failed = false;
+    let pending = 1; // released after the loop, so a sweep with nothing to do also settles
+    const settle = () => {
+      if (--pending !== 0) return;
+      if (failed) this.#scheduleSweep();
+      else this.#backoffMs = RECONNECT_MIN_MS;
+    };
